-- Volcando datos para la tabla tenekbeer.tnk_experiencias: ~2 rows (aproximadamente)
INSERT INTO `tnk_experiencias` (`id`, `descripcion`, `imagen_url`, `created_at`, `updated_at`) VALUES
	(1, 'En TENEK somos una cervecería artesanal mexicana fundada en 2019 con la convicción de que una cerveza puede ser mucho más que una bebida. Creemos que cada botella tiene el poder de contar una historia, despertar emociones y conectar a las personas con la riqueza cultural de nuestro país.\nDesde nuestros inicios nos propusimos crear cervezas artesanales de alta calidad que combinan excelencia técnica, creatividad e innovación. Cada receta nace de un cuidadoso proceso de selección de ingredientes y de una elaboración precisa que nos permite ofrecer sabores auténticos, equilibrados y memorables, con personalidad propia en cada estilo.\n', 'experiencias/01M1PXG9KWCBRP794XJ3M2C73M.webp', '2026-09-05 01:14:37', '2026-09-05 01:14:37'),
	(2, 'Nuestra mayor inspiración es México: un país lleno de tradiciones, paisajes, sabores e historias que se expresan de manera única en cada región. Esa diversidad cultural impulsa nuestra creatividad y nos motiva a desarrollar cervezas que reinterpretan la esencia de nuestro país desde una visión contemporánea, invitando a descubrir nuevas experiencias en cada sorbo.\nEn TENEK entendemos que el sabor también comunica. Por eso, cada una de nuestras cervezas busca transmitir el carácter, la pasión y el orgullo que distinguen a México, convirtiendo cada brindis en una oportunidad para compartir, explorar y crear recuerdos.\n', 'experiencias/01M1PXH31R7P2KEXJD33FJWXKQ.webp', '2026-09-05 01:15:03', '2026-09-05 01:15:03'),
	(3, 'La calidad es el fundamento de todo lo que hacemos. Trabajamos con disciplina, mejoramos constantemente nuestros procesos y cuidamos cada detalle para ofrecer una cerveza artesanal premium que responda a las expectativas de quienes valoran la autenticidad, el diseño y el buen gusto.\nMás que elaborar cerveza, construimos experiencias que celebran la diversidad cultural de México y acercan a las personas a nuevas historias por descubrir.\n', 'experiencias/01M1PXJ2P2Z0242SPD6G9JZKVW.webp', '2026-09-05 01:15:35', '2026-09-05 01:15:35');

